  enhanced, colback=bgdeep, colframe=bgdeep, colupper=textwhite,
  arc=0pt, boxrule=0pt,
  left=10pt, right=10pt, top=30pt, bottom=10pt,
  halign=center, valign=center,
]{name=title, column=1, span=3, between=top and row3}{
  {\fontsize{130}{150}\selectfont\bfseries\color{cyan} WEB SUMMIT LISBON 2026}\\[30pt]
  {\fontsize{60}{70}\selectfont\bfseries\color{textwhite} WHERE THE FUTURE MEETS NOW}\\[30pt]
