  halign=center, valign=center,
  drop shadow={opacity=0.8, color=black}
]{name=offer, column=1, span=3, between=row3 and row6}{
  {\fontsize{180}{190}\selectfont\bfseries 50\% SAVINGS}\\[30pt]
  {\fontsize{80}{90}\selectfont\bfseries 2-FOR-1 TICKET PROMOTION}\\[30pt]
  {\fontsize{55}{65}\selectfont\bfseries\color{bgdeep} 24 HOURS ONLY — DON'T MISS OUT!}
}

