\posterbox[promocard=cyan, title={WORLD-CLASS SPEAKERS}
]{name=speakers, column=1, span=1, between=row6 and row16}{
  \fontsize{38}{58}\selectfont
  Join legendary tech founders, policymakers, and global icons.\vspace{20pt}

  \begin{itemize}[itemsep=18pt, label={\color{cyan}$\blacksquare$}, leftmargin=*]
    \item \textbf{Sam Altman}\\(OpenAI)
    \item \textbf{Geoffrey Hinton}\\(Godfather of AI)
    \item \textbf{Ursula von der Leyen}\\(European Commission)
    \item \textbf{António Guterres}\\(United Nations)
    \item \textbf{Alexis Ohanian}\\(Reddit)
    \item \textbf{Serena Williams}\\(Tennis Champion)
    \item \textbf{Ryan Reynolds}\\(Actor \& Entrepreneur)
    \item \textbf{Pharrell Williams}\\(Artist \& Entrepreneur)
    \item \textbf{Doug Leone}\\(Sequoia Capital)
    \item \textbf{Anton Osika}\\(Lovable)
  \end{itemize}
}

\posterbox[promocard=green, title={AN ECOSYSTEM FOR EVERYONE}
]{name=ecosystem, column=2, span=1, between=row6 and row16}{
  \centering
  \vspace{30pt}
  \colorbox{green!15}{\parbox{0.8\linewidth}{
    \centering\vspace{30pt}
    {\fontsize{110}{120}\selectfont\bfseries\color{green} 70,000+}\\[20pt]
    {\fontsize{45}{55}\selectfont\bfseries ATTENDEES}\vspace{30pt}
  }}\vspace{50pt}

  \raggedright
  \fontsize{38}{58}\selectfont
  Tailored programming for all:\vspace{20pt}

  \begin{itemize}[itemsep=18pt, label={\color{green}$\blacksquare$}, leftmargin=*]
    \item \textbf{Startups}\\Startup programme, impact
    \item \textbf{Investors}\\Venture meetups, tracks
    \item \textbf{Partners}\\Brand activations, halls
    \item \textbf{Media}\\Global press access
    \item \textbf{Attendees}\\Night Summit, meetups
  \end{itemize}
}

