  halign=center, valign=center,
  drop shadow={opacity=0.8, color=black}
]{name=cta, column=1, span=3, between=row16 and row19}{
  {\fontsize{90}{100}\selectfont\bfseries PRE-REGISTER NOW}\\[30pt]
  {\fontsize{50}{60}\selectfont\bfseries SECURE YOUR 2-FOR-1 TICKETS BEFORE THEY SELL OUT}\\[30pt]
  {\fontsize{45}{55}\selectfont\bfseries\color{bgdeep!80} WEBSUMMIT.COM/2026}
}

% ══ FOOTER ══
